// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address nonOwner = address(0xBEEF);

    function setUp() public { c = new C(); }

    // fuzzed params: amount to fund the contract and amount the caller sends when calling withdraw
    function testFuzz_property(uint256 fundAmount, uint256 callerBalance) public {
        // keep amounts reasonable but wide
        fundAmount = bound(fundAmount, 1 wei, 1 ether);
        callerBalance = bound(callerBalance, 0 wei, 1 ether);

        // Fund the contract from some account (the owner created in setUp() is address(this) in that context? actually new C() sets Owner to msg.sender which was this test contract)
        // The test contract is the Owner of c. We will fund c from any other account.
        address funder = address(0xABCD);
        vm.deal(funder, fundAmount);
        vm.prank(funder);
        (bool okFund,) = address(c).call{value: fundAmount}("");
        require(okFund);

        // Give the nonOwner some balance to act with
        vm.deal(nonOwner, callerBalance);

        // The distinguishing action: a non-owner calls withdraw.
        // Under the reference contract, this call must fail (or at least must not transfer funds away leaving balance zero) because require(msg.sender == Owner) prevents non-owner success.
        // Under the mutant that removed the require, the non-owner call will succeed and drain the contract, making address(c).balance == 0 for some inputs (when fundAmount>0).

        bool ok;
        vm.prank(nonOwner);
        try c.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General property to assert: after a non-owner attempts withdraw, the contract balance must remain equal to the original funded amount (i.e., non-owner cannot drain it).
        // We read address(c).balance as the observable.
        // If the mutant removed the require, for some inputs (fundAmount>0) the non-owner call will succeed and address(c).balance will become 0, violating this assertion.
        assertTrue(address(c).balance == fundAmount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: an attacker address and an amount to fund the contract
    function testFuzz_property(address caller, uint256 fundAmount) public {
        // keep fundAmount in a reasonable but wide domain (allow 1..1e30)
        fundAmount = bound(fundAmount, 1, 1e30);
        // avoid the zero address as a caller for clarity
        vm.assume(caller != address(0));

        // fund the caller so they can send fundAmount
        vm.deal(caller, fundAmount);

        // Caller sends ETH to the contract to create a non-zero balance
        vm.prank(caller);
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent);

        // Now attempt to have `caller` call withdraw(). On the reference contract,
        // only Owner (deployer) can empty the contract, so a non-owner caller
        // should not make address(c).balance == 0. The mutant allowing anyone
        // to withdraw will let some non-owner caller make the balance 0.

        // perform the withdraw call as `caller` and capture success via try/catch
        bool ok;
        vm.prank(caller);
        try c.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: after caller calls withdraw, the contract balance is zero
        // iff the caller is the Owner. This is a universal property the reference
        // satisfies for all inputs; the mutant (which removes the require) will
        // allow a non-owner caller to make the balance zero for some inputs.
        address owner = address(c.Owner());
        if (caller == owner) {
            // Owner calling should be able to empty the contract
            assertTrue(address(c).balance == 0);
        } else {
            // Non-owner calling MUST NOT empty the contract on the correct reference
            assertTrue(address(c).balance != 0);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: caller (address) and fund amount
    function testFuzz_property(address caller, uint256 fund) public {
        // keep fund in a reasonable range but wide enough to include zero and large values
        fund = bound(fund, 0, 1 ether);

        // Ensure caller is not the Owner (Owner is deployer, i.e., address(this) in setUp context)
        // If the fuzzer picks the Owner, we still allow it: the universal property must hold for ALL inputs
        // but the distinguishing behavior is when caller != Owner — the mutant will allow non-Owner to drain.

        // Fund the contract from some rich account (use address(1))
        vm.deal(address(1), fund);
        vm.prank(address(1));
        (bool sent,) = payable(address(c)).call{value: fund}('');
        require(sent);

        uint256 before = address(c).balance;

        // Now attempt withdraw as the fuzzed caller
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        bool ok;
        try c.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = address(c).balance;

        // General rule (single assertion): If the caller is NOT the Owner, then the withdraw call must NOT change the contract balance.
        // This holds for the reference contract for ALL inputs, but the mutant (which removes the Owner require) will allow some non-Owner caller to drain the balance, making this assertion fail for some fuzz input.
        if (caller != address(this)) {
            assertTrue(after == before);
        } else {
            // If caller == Owner, reference allows balance to become zero; assert nothing about that case — still must have exactly one assertTrue executed in all runs.
            // To satisfy the single-assert requirement, make a tautology about Owner calling: owner calling may or may not change balance, so assert true via checking equality-or-zero.
            assertTrue(after == before || after == 0);
        }
    }
}

