pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amt) public {
        // keep amount reasonable within balanceable range
        amt = bound(amt, 0, 1 ether);

        // fund the contract from owner so it has a balance to withdraw
        address owner = address(this); // our test deployed contract is msg.sender in setUp -> Owner
        vm.deal(owner, 2 ether);
        // send some ether into c from owner so C has balance
        vm.prank(owner);
        (bool s,) = address(c).call{value: amt}("\x00");
        require(s);

        // try to have the fuzzed caller invoke withdraw
        vm.deal(caller, 1 ether);
        bool ok;
        vm.prank(caller);
        try c.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: in the correct contract only the Owner can successfully call withdraw;
        // therefore any non-Owner caller's withdraw attempt must revert (ok == false).
        // This will be true for all inputs on the reference, but the mutant that removes the
        // require allows some non-Owner caller to succeed, causing this assertion to fail for those inputs.
        if (caller != owner) {
            assertTrue(!ok);
        } else {
            // Owner should be able to withdraw successfully (sanity for completeness)
            assertTrue(ok);
        }
    }
}

