pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: caller address and initial funding amount
    function testFuzz_property(address caller, uint256 fund) public {
        // Keep fund reasonably bounded so vm.deal works and avoid overflow edgecases
        fund = bound(fund, 0, 1 ether);

        // Ensure caller is not the Owner (c.Owner() is the deployer set in setUp())
        // If the fuzzer picks the Owner address, change it slightly to another EOA
        address owner = c.Owner();
        if (caller == owner) {
            // choose a different address deterministically derived from caller
            caller = address(uint160(uint256(keccak256(abi.encodePacked(caller, "alt")))));
            // still guard against accidental equality (extremely unlikely)
            if (caller == owner) caller = address(1);
        }

        // Fund the contract with `fund` from an external account (use address(2) as funder)
        address funder = address(2);
        vm.deal(funder, fund);
        vm.prank(funder);
        (bool sent,) = address(c).call{value: fund}("");
        require(sent, "funding failed");

        uint256 before = address(c).balance;

        // Attempt withdraw as the fuzzed caller
        vm.deal(caller, 1 ether); // give caller some ETH to pay gas (not strictly needed but safe)
        bool ok;
        vm.prank(caller);
        try c.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 after = address(c).balance;

        // SINGLE assertion: For non-Owner callers, the reference contract should never reduce its balance via withdraw()
        // (i.e., after == before). The mutant that removes the require will allow some non-Owner to empty the contract,
        // making after < before for some inputs — the fuzzer will find such a counterexample on the mutant.
        assertTrue(after == before);
    }
}

