pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: amount to fund the contract, and an arbitrary ownerPrivKey (fuzzed) used to derive an owner EOA
    function testFuzz_property(uint256 fundAmount, uint256 ownerPrivKey) public {
        // Keep fundAmount in a reasonable wide domain but non-zero
        fundAmount = bound(fundAmount, 1, type(uint256).max / 4);
        // Derive an address for owner EOA from the fuzzed private key
        address owner = vm.addr(ownerPrivKey);

        // Ensure the derived owner is the contract Owner (the contract set Owner = msg.sender on deployment)
        // We deployed c in setUp() from this test contract, so Owner is address(this). To exercise the real Owner path,
        // we need Owner to be the caller of withdraw. So we simulate contract constructed by a different deployer.
        // To achieve that without redeploying C (setUp already did), we will instead fund c and call withdraw as the known Owner (the deployer).
        // The contract's Owner is msg.sender at deployment time, which was this test contract. So Owner == address(this).
        // We'll make address(this) be the caller when invoking withdraw by using vm.startPrank(address(this)) (no-op) — but we must call withdraw from the Owner account.
        // Ensure the contract has balance by sending fundAmount from some EOA.

        // Use an arbitrary funder EOA derived from a different fuzzed key
        uint256 funderKey = ownerPrivKey + 1;
        address funder = vm.addr(funderKey);
        vm.deal(funder, fundAmount);

        // fund the contract
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: fundAmount}(abi.encodeWithSignature(""));
        require(sent, "funding failed");

        // Record balances before withdraw
        uint256 ownerBalanceBefore = address(this).balance; // Owner is this test contract (deployer of c)
        uint256 contractBalanceBefore = address(c).balance;

        // Sanity: contract must have the funded amount
        vm.assume(contractBalanceBefore == fundAmount);

        // Call withdraw as the Owner (this contract)
        // No vm.prank needed because this test contract is the Owner
        // Capture whether call succeeded (should succeed in reference and mutant since require passes)
        bool ok;
        try c.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After withdraw: in the reference, entire contract balance moved to Owner (this), so address(c).balance == 0
        // The mutant sends to msg.sender (but since msg.sender == Owner here, both behave same). To expose the mutant we need a case where msg.sender != Owner.
        // Therefore, we now exercise withdraw where caller is Owner? The bug only manifests when withdraw is called by Owner but recipient differs: Owner vs msg.sender — however when caller == Owner, msg.sender == Owner so both identical.
        // To make them differ we need Owner to be different from the caller while still passing the require(msg.sender == Owner). That's impossible. The real distinguishing scenario is when Owner state variable was intended recipient but mutant uses msg.sender — difference arises when Owner != msg.sender; however require enforces equality, so difference manifests only if Owner value changed between deployment and call (e.g., via delegatecall or reentrancy). But given the one-statement mutant described, a clear distinguishing test is to observe that reference always leaves address(c).balance == 0 after successful withdraw, whereas a mutant that transfers to msg.sender also leaves address(c).balance == 0. To construct a failing case, we instead exploit that Owner getter must equal the deployer; ensure the property: after withdraw by Owner, address(c).balance == 0.
        // This holds for the reference for all inputs. The mutant also satisfies this when caller == Owner, but since the required mutation description states mutant changes recipient to msg.sender, a failing input exists when Owner variable is a different address than the caller at call-time — that cannot pass require. Given constraints, the reliable universal property to assert on the reference is: after withdraw by Owner, address(c).balance == 0. The mutant will fail for some scenarios where Owner state was externally changed before withdraw (not present here) but per instructions we must assert exactly one property; we assert the reference's contract balance is zero after withdraw.

        assertTrue(address(c).balance == 0);
    }
}

