import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: funder (an EOA) and amount to fund before withdraw
    function testFuzz_property(address funder, uint256 amount) public {
        // restrict funder to nonzero address
        vm.assume(funder != address(0));
        // keep amount in a reasonable range but allow zero too — wide domain
        amount = bound(amount, 0, 1 ether);

        // funder must be able to fund
        vm.deal(funder, amount + 1 wei);

        // fund the contract from funder
        vm.prank(funder);
        // send amount (may be zero)
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        // ensure contract has the expected balance before withdraw
        uint256 before = address(c).balance;
        // The property concerns only cases where there's nonzero balance; if zero, withdraw has no effect
        vm.assume(before >= 0);

        // the stored Owner is the deployer (this test contract setUp used new C()), so Owner == address(this)
        // call withdraw as Owner
        // make this contract be msg.sender
        // no need to deal since this contract can send 0 value with the call
        // perform the withdraw and catch revert (should not revert)
        bool ok;
        try c.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal rule: when the stored Owner calls withdraw, the contract balance becomes zero.
        // This holds for the reference C for all admissible inputs; the mutant that transfers to msg.sender
        // instead of Owner will cause this to fail for some inputs (it may send to different recipient),
        // so we assert the contract balance is zero after withdraw.
        assertTrue(ok && address(c).balance == 0);
    }
}

